const BLOG_API_BASE =
  process.env.NEXT_PUBLIC_BLOG_API_URL || "http://localhost:4000/api/v1";

export type PartnerIcon =
  | "mastercard"
  | "agric"
  | "mechanization"
  | "amta"
  | "womeninmech"
  | "ikore"
  | "sanekonsult";

export const PARTNERS: { name: PartnerIcon; label: string; kicker?: string }[] = [
  {
    name: "mastercard",
    label: "Mastercard Foundation",
    kicker: "in partnership with",
  },
  { name: "agric", label: "Federal Ministry of Agriculture and Food Security" },
  { name: "mechanization", label: "National Centre for Agricultural Mechanization" },
  { name: "amta", label: "AMTA" },
  { name: "womeninmech", label: "Women in Mechanized Agriculture" },
  { name: "ikore", label: "IKORE" },
  { name: "sanekonsult", label: "Sane Konsult International Limited" },
];

type InsightTagTone = "orange" | "teal" | "indigo";

interface BlogPostPreview {
  id: string;
  title: string;
  excerpt: string;
  slug: string;
  date: string;
  imageUrl: string;
  imageAlt: string;
  category: string;
  tagTone: InsightTagTone;
}

function stripHtml(html: string): string {
  return html
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .replace(/&nbsp;/g, " ")
    .trim();
}

function excerptPlain(html: string, max: number): string {
  const s = stripHtml(html);
  if (!s) return "";
  if (s.length <= max) return s;
  return `${s.slice(0, max).trim()}…`;
}

function formatPostDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
}

interface Post {
  id: string;
  title: string;
  excerpt: string;
  slug: string;
  date: string;
  featuredImage?: {
    node?: {
      sourceUrl?: string;
      altText?: string;
    };
  };
}

const TAG_TONES: InsightTagTone[] = ["orange", "teal", "indigo"];

// Mirror app/components/blogCarouselSection.tsx so both surfaces hit the blog
// API the same way and can be cached together by Next.js.
async function getPosts(): Promise<Post[]> {
  try {
    const res = await fetch(`${BLOG_API_BASE}/blog?limit=12&page=1`, {
      next: { revalidate: 60 },
    });
    if (!res.ok) return [];
    const json = await res.json();
    return Array.isArray(json?.data) ? json.data : [];
  } catch (error) {
    console.log("Error fetching posts for TractracPartnersInsightsSection:", error);
    return [];
  }
}

// Revalidate the section every 60 seconds, matching blogCarouselSection.
export const revalidate = 60;

