function mapApiToInsights(posts: Post[]): BlogPostPreview[] {
  return posts.slice(0, 3).map((p, i) => ({
    id: p.id,
    title: p.title,
    excerpt: excerptPlain(p.excerpt || "", 200),
    slug: p.slug,
    date: p.date,
    imageUrl: p.featuredImage?.node?.sourceUrl || STATIC_INSIGHTS[i % 3].imageUrl,
    imageAlt: p.featuredImage?.node?.altText || p.title,
    category: "Insights",
    tagTone: TAG_TONES[i % 3],
  }));
}

const INSIGHT_TAG_CLASS: Record<InsightTagTone, string> = {
  orange: styles.insightCategory_orange,
  teal: styles.insightCategory_teal,
  indigo: styles.insightCategory_indigo,
};

function insightHref(slug: string): string {
  return slug ? `/blog/${encodeURIComponent(slug)}` : "/blog";
}


