export default async function TractracPartnersInsightsSection() {
  const posts = await getPosts();
  const insights =
    posts.length >= 3 ? mapApiToInsights(posts) : STATIC_INSIGHTS;

  return (
    <>
      <section className={styles.partners} aria-labelledby="tractrac-partners-heading">
        <div className={styles.partnersInner}>
          <p className={styles.partnersKicker}>Partners</p>
          <h2 id="tractrac-partners-heading" className={styles.partnersTitle}>
            {bindTitleOrphans("Mechanizing Africa Through Bold Collaboration")}
          </h2>
          <p className={styles.partnersSub}>
            We work alongside leading institutions committed to transforming agriculture and building a
            prosperous Africa.
          </p>

          <ul className={styles.partnersStripWrap} aria-label="TracTrac partners">
            {PARTNERS.map((p) => (
              

                  <PartnerIconSvg name={p.name} stroke="currentColor" />
            ))}
          </ul>
        </div>
      </section>

      <section className={styles.insights} aria-labelledby="tractrac-insights-heading">
        <div className={styles.insightsInner}>
          <div className={styles.insightsTop}>
            <div className={styles.insightsTopLeft}>
              <p className={styles.insightsTag}>
                {/* <span className={styles.insightsTagDot} aria-hidden /> */}
                <span>Insights &amp; News</span>
              </p>
              <h2 id="tractrac-insights-heading" className={styles.insightsTitle}>
                {bindTitleOrphans("Our Insights, News & Perspectives")}
              </h2>
            </div>
            <Link href="/blog" className={styles.insightsViewAll}>
              View All Articles →
            </Link>
          </div>

          <div className={styles.insightsGrid}>
            {insights.map((article) => (
              <article key={article.id} className={styles.insightCard}>
                <Link href={insightHref(article.slug)} className={styles.insightCardLink}>
                  <div className={styles.insightImageWrap}>
                    {/* eslint-disable-next-line @next/next/no-img-element -- featured images may come from any blog CDN */}
                    <img
                      src={article.imageUrl}
                      alt={article.imageAlt}
                      className={styles.insightImg}
                      loading="lazy"
                    />
                  </div>
                  <div className={styles.insightBody}>
                    <div className={styles.insightMeta}>
                      <span
                        className={`${styles.insightCategory} ${INSIGHT_TAG_CLASS[article.tagTone]}`}
                      >
                        {article.category}
                      </span>
                      <time className={styles.insightDate} dateTime={article.date}>
                        {formatPostDate(article.date)}
                      </time>
                    </div>
                    <h3 className={styles.insightCardTitle}>{article.title}</h3>
                    <p className={styles.insightExcerpt}>{article.excerpt}</p>
                    <span className={styles.insightRead}>Read Article →</span>
                  </div>
                </Link>
              </article>
            ))}
          </div>
        </div>
      </section>
    </>
  );
}
